# -*- coding: utf-8 -*-

def main():
    N, A, B = map(int, input().split())
    S = input()

    ans = 0
    X = [0] * (N * 2 + 1)
    for i in range(N * 2):
        if S[i] == "(":
            X[i + 1] = 1
        if S[i] == ")":
            X[i + 1] = -1

    K = sum(X)
    ans += B * abs(K) // 2
    if K > 0:
        for i in range(N * 2):
            if X[N * 2 - i] == 1:
                X[N * 2 - i] = -1
                K -= 2
                if K == 0:
                    break

    if K < 0:
        for i in range(N * 2):
            if X[i + 1] == -1:
                X[i + 1] = 1
                K += 2
                if K == 0:
                    break

    for i in range(N * 2):
        X[i + 1] += X[i]

    M = abs(min(X))
    if M % 2 != 0:
        M += 1
    ans += min(A * M // 2, 2 * B * M // 2)
    print(ans)
